import csv
import re
from datetime import datetime, date
from io import BytesIO, StringIO
from zipfile import ZipFile, BadZipFile

import pandas as pd

FIELDS = {
    'period': 'Date / month', 'revenue': 'Net sales revenue',
    'cogs': 'Cost of goods / ingredients', 'payroll': 'Payroll including employer costs',
    'rent': 'Occupancy / rent', 'other': 'Other operating costs', 'amount': 'Amount',
}
COSTS = ['cogs', 'payroll', 'rent', 'other']
FINANCIAL = ['revenue'] + COSTS
ALIASES = {
    'period': ['date', 'month', 'period', 'reporting month', 'transaction date', 'sale date', 'invoice date', 'posting date', 'accounting period'],
    'revenue': ['revenue', 'sales', 'net sales', 'net revenue', 'sales revenue', 'turnover', 'monthly sales', 'net takings'],
    'cogs': ['cogs', 'cost of goods', 'cost of goods sold', 'cost of sales', 'ingredients', 'food cost', 'ingredient costs'],
    'payroll': ['payroll', 'wages', 'staff cost', 'staff costs', 'labour costs', 'labor costs', 'salaries', 'employee costs'],
    'rent': ['rent', 'occupancy', 'occupancy costs', 'lease expense', 'premises cost'],
    'other': ['other', 'other expenses', 'other costs', 'other operating costs', 'overheads', 'operating overhead'],
    'amount': ['amount', 'value', 'net amount', 'transaction amount', 'total amount', 'paid amount'],
}


def normalise(value):
    value = re.sub(r'([a-z])([A-Z])', r'\1 \2', str(value))
    value = re.sub(r'\b(cad|usd|gbp|eur)\b', '', value.lower())
    return re.sub(r'[^a-z0-9]+', ' ', value).strip()


def table_hint(name):
    """Reviewable defaults from familiar table names; not inferred accounting truth."""
    words=set(normalise(name).split())
    if words & {'monthly','summary','history'}:
        return 'Monthly summary','other'
    for field,terms in [('cogs',{'ingredient','ingredients','supplier','purchases','cogs'}),
                        ('payroll',{'payroll','wages','salaries'}),
                        ('rent',{'occupancy','premises','rent'}),
                        ('other',{'expenses','operating','overhead'})]:
        if words & terms:
            return 'Expense transactions',field
    if words & {'sales','pos','receipts'}:
        return 'Sales transactions','other'
    return 'Monthly summary','other'


def suggestions(frame, fields):
    """Exact normalized synonyms only. Competing candidates require a human choice."""
    result, evidence = {}, []
    for field in fields:
        matches = [c for c in frame.columns if normalise(c) in ALIASES[field]]
        chosen = matches[0] if len(matches) == 1 else None
        result[field] = chosen
        evidence.append({'Field': FIELDS[field], 'Suggested column': chosen or 'Choose manually',
                         'Reason': 'Recognised heading synonym' if chosen else 'Multiple candidates: ' + ', '.join(matches) if matches else 'No confident heading match',
                         'Examples': ', '.join(str(x)[:40] for x in frame[chosen].head(3)) if chosen else ''})
    return result, pd.DataFrame(evidence)


def sheet_names(content):
    if not content or len(content) > 20 * 1024 * 1024:
        raise ValueError('Choose a non-empty file under 20 MB.')
    try:
        with ZipFile(BytesIO(content)) as archive:
            if sum(i.file_size for i in archive.infolist()) > 100 * 1024 * 1024:
                raise ValueError('The expanded workbook exceeds 100 MB.')
        with pd.ExcelFile(BytesIO(content), engine='openpyxl') as book:
            return book.sheet_names
    except Exception as exc:
        raise ValueError('Could not open workbook sheets. Use an unprotected .xlsx under the size limit.') from exc


def read_file(content, filename, sheet=None, header_row=1):
    if not content or len(content) > 20 * 1024 * 1024:
        raise ValueError('Choose a non-empty file under 20 MB.')
    if not 1 <= header_row <= 50:
        raise ValueError('The header must be within the first 50 rows.')
    try:
        if filename.lower().endswith('.xlsx'):
            with ZipFile(BytesIO(content)) as archive:
                if sum(i.file_size for i in archive.infolist()) > 100 * 1024 * 1024:
                    raise ValueError('The expanded workbook exceeds 100 MB. Export a smaller sheet as CSV.')
            with pd.ExcelFile(BytesIO(content), engine='openpyxl') as book:
                sheets = book.sheet_names
                raw = pd.read_excel(book, sheet_name=sheet or sheets[0], header=None, dtype=object, keep_default_na=False, nrows=50002)
        elif filename.lower().endswith('.csv'):
            decoded = content.decode('utf-8-sig')
            try:
                delimiter = csv.Sniffer().sniff('\n'.join(decoded.splitlines()[header_row-1:header_row+10]), delimiters=',;\t|').delimiter
            except csv.Error:
                delimiter = ','
            rows = list(csv.reader(StringIO(decoded), delimiter=delimiter))
            raw = pd.DataFrame(rows).fillna('')
            sheets = []
        else:
            raise ValueError('Choose .xlsx or UTF-8 .csv.')
    except (ValueError, UnicodeError, BadZipFile) as exc:
        raise ValueError('Could not read the file: ' + str(exc)) from exc
    except Exception as exc:
        raise ValueError('Could not open this workbook. Try an unprotected .xlsx or UTF-8 CSV export.') from exc
    if len(raw) <= header_row:
        raise ValueError('No records below this header. Choose another header row or worksheet.')
    if len(raw) > 50001:
        raise ValueError('Use at most 50,000 records per file in this version.')
    if raw.shape[1] > 100:
        raise ValueError('Use at most 100 columns in this version.')
    headers, counts = [], {}
    for i, item in enumerate(raw.iloc[header_row-1]):
        label = str(item).strip() or f'Unnamed column {i+1}'
        counts[label] = counts.get(label, 0) + 1
        headers.append(label if counts[label] == 1 else f'{label} [column {i+1}]')
    frame = raw.iloc[header_row:].copy().reset_index(drop=True)
    frame.columns = headers
    return frame, sheets


def number(value):
    """Dot decimal, properly grouped comma thousands, optional $ and parentheses."""
    if pd.isna(value) or str(value).strip() in ('', '-', '—', 'N/A', 'n/a'):
        return None
    raw = str(value).strip()
    neg = raw.startswith('(') and raw.endswith(')')
    raw = raw[1:-1] if neg else raw
    raw = re.sub(r'\s+CAD$', '', raw, flags=re.I).strip()
    raw = re.sub(r'^(?:CAD\s*)?\$?\s*', '', raw, flags=re.I).strip()
    if neg and raw.startswith(('-', '+')):
        raise ValueError('Use either parentheses or a minus sign for a negative amount, not both.')
    if not re.fullmatch(r'[+-]?(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?', raw):
        raise ValueError('Use a number such as 1234.50 or 1,234.50; no currency conversion is performed.')
    out = float(raw.replace(',', '')) * (-1 if neg else 1)
    if not abs(out) <= 1e12:
        raise ValueError('Amount exceeds the supported range.')
    return out


def month(value, order='ISO / year first'):
    if isinstance(value, (datetime, date, pd.Timestamp)) and not pd.isna(value):
        return pd.Timestamp(value).to_period('M').to_timestamp()
    text = str(value).strip()
    formats = ['%Y-%m', '%Y-%m-%d', '%Y/%m/%d', '%Y-%m-%d %H:%M:%S', '%Y-%m-%dT%H:%M:%S']
    formats += ['%b %Y', '%B %Y', '%b-%Y', '%B-%Y', '%Y/%m']
    formats += {'Day first': ['%d/%m/%Y', '%d-%m-%Y'], 'Month first': ['%m/%d/%Y', '%m-%d-%Y']}.get(order, [])
    for fmt in formats:
        try:
            return pd.Timestamp(datetime.strptime(text, fmt)).to_period('M').to_timestamp()
        except ValueError:
            pass
    raise ValueError('Missing or unrecognised date. Choose the date order or use YYYY-MM-DD / YYYY-MM.')


def analyse(frame, mapping, mode='Monthly summary', expense_field='other', order='ISO / year first', header_row=1, today=None, negative_expenses=False):
    fields = FINANCIAL if mode == 'Monthly summary' else ['amount']
    selected = [v for v in mapping.values() if v]
    if not mapping.get('period'):
        raise ValueError('Choose the date / month column.')
    if len(selected) != len(set(selected)):
        raise ValueError('A source column cannot be used for more than one field.')
    if any(c not in frame.columns for c in selected):
        raise ValueError('A mapped column no longer exists. Review the column choices.')
    if not any(mapping.get(f) for f in fields):
        raise ValueError('Choose at least one financial amount column.')
    if frame.empty:
        raise ValueError('No records to analyse. Add at least one monthly figure or transaction.')
    blank = frame.apply(lambda col: col.map(lambda v: pd.isna(v) or str(v).strip()=='' )).all(axis=1).reset_index(drop=True)
    today = pd.Timestamp(today or date.today()).to_period('M').to_timestamp()
    records, issues = [], []
    for pos, (_, row) in enumerate(frame.iterrows()):
        item = {'source_row': pos+header_row+1, 'period': pd.NaT}
        if blank.iloc[pos]:
            for f in fields:
                target=f if mode=='Monthly summary' else 'revenue' if mode=='Sales transactions' else expense_field
                item[target]=None
            records.append(item)
            issues.append({'Source row':item['source_row'],'Field':'row','Issue':'Blank spacer row; retained in the audit and ignored in monthly totals.'})
            continue
        try:
            item['period'] = month(row[mapping['period']], order)
            if item['period'] >= today:
                raise ValueError('Current or future month: this baseline uses completed historical months only.')
        except ValueError as exc:
            issues.append({'Source row': item['source_row'], 'Field': 'period', 'Issue': str(exc)})
            item['period'] = pd.NaT
        for f in fields:
            target = f if mode == 'Monthly summary' else 'revenue' if mode == 'Sales transactions' else expense_field
            item[target] = None
            if not mapping.get(f):
                continue
            try:
                value = number(row[mapping[f]])
                if value is None:
                    raise ValueError('Missing amount; this field-month stays unknown, not zero.')
                if mode == 'Expense transactions' and negative_expenses:
                    value *= -1
                if mode == 'Monthly summary' and value < 0:
                    raise ValueError('Negative monthly total: review refunds/credits before using this month.')
                item[target] = value
            except ValueError as exc:
                issues.append({'Source row': item['source_row'], 'Field': target, 'Issue': str(exc)})
        records.append(item)
    rows = pd.DataFrame(records)
    mapped_fields = [f for f in FINANCIAL if f in rows and (mapping.get(f) if mode == 'Monthly summary' else True)]
    duplicate = frame.astype(str).duplicated(keep=False).reset_index(drop=True) & ~blank
    # Duplicate summary months are ambiguous even if row values differ.
    dup_month = rows['period'].notna() & rows['period'].duplicated(keep=False) if mode == 'Monthly summary' else pd.Series(False, index=rows.index)
    blocked = duplicate | dup_month
    for i in rows.index[blocked]:
        issues.append({'Source row': int(rows.loc[i, 'source_row']), 'Field': 'row',
                       'Issue': 'Possible duplicate record / repeated summary month. Resolve or confirm separate transactions before combining.'})
    grouped = []
    for period, group in rows.dropna(subset=['period']).groupby('period'):
        entry = {'period': period}
        for field in mapped_fields:
            vals = group[field]
            entry[field] = float(vals.sum()) if vals.notna().all() and not blocked.loc[group.index].any() else float('nan')
            if pd.notna(entry[field]) and entry[field] < 0:
                entry[field] = float('nan')
                issues.append({'Source row': ', '.join(str(int(x)) for x in group.source_row), 'Field': field, 'Issue': 'Net monthly amount is negative; review the sign convention or credits.'})
        grouped.append(entry)
    monthly = pd.DataFrame(grouped, columns=['period']+mapped_fields)
    # Unknown-date amounts could belong to any month: do not certify those field totals.
    if (rows.period.isna() & ~blank).any():
        for field in mapped_fields:
            monthly[field] = float('nan')
    return {'rows': rows, 'monthly': monthly, 'issues': pd.DataFrame(issues, columns=['Source row','Field','Issue']),
            'ignored': [c for c in frame.columns if c not in selected], 'mapped_fields': mapped_fields}


def combine(results):
    """Never add overlapping sources automatically (e.g. totals and transactions)."""
    values, conflicts = {}, []
    for source, result in results:
        for _, row in result['monthly'].iterrows():
            for field in result['mapped_fields']:
                key = (row['period'], field)
                if key in values:
                    conflicts.append({'Month': str(row['period'].date()), 'Field': field, 'Sources': values[key][1] + ' / ' + source})
                    values[key] = (float('nan'), values[key][1] + ' / ' + source)
                else:
                    values[key] = (row[field], source)
    months = sorted({k[0] for k in values})
    monthly = pd.DataFrame([{'period': m, **{f: values.get((m,f), (float('nan'),''))[0] for f in FINANCIAL}} for m in months], columns=['period']+FINANCIAL)
    return monthly, pd.DataFrame(conflicts)


def baseline(monthly):
    out, coverage = {}, []
    for field in FINANCIAL:
        known = monthly.dropna(subset=[field]) if field in monthly else pd.DataFrame()
        out[field] = float(known[field].mean()) if len(known) else None
        coverage.append({'Field': FIELDS[field], 'Complete months': len(known), 'Average per complete month': out[field],
                         'Months used': ', '.join(known.period.dt.strftime('%Y-%m')) if len(known) else 'None'})
    pairs = monthly.dropna(subset=['revenue','cogs']) if len(monthly) else pd.DataFrame()
    out['cogs_ratio'] = float(pairs.cogs.sum()/pairs.revenue.sum()) if len(pairs) and pairs.revenue.sum() > 0 else None
    return out, pd.DataFrame(coverage)


def safe_csv(frame):
    """Neutralize spreadsheet formulas in user-controlled text exports."""
    out = frame.copy()
    for col in out.columns:
        out[col] = out[col].map(lambda x: "'"+x if isinstance(x,str) and x.lstrip().startswith(('=', '+', '-', '@')) else x)
    return out.to_csv(index=False).encode('utf-8-sig')


def issue_help(issues):
    """Attach a concrete next step without changing source values or validation."""
    out=issues.copy()
    def action(text):
        if 'Blank spacer' in text: return 'No correction needed. This empty row contributes no amounts.'
        if 'date' in text.lower() or 'historical months' in text: return 'Choose the date order or correct the date. Use a completed month; put future estimates in Build your plan.'
        if 'duplicate' in text.lower(): return 'Check repeated rows/months. Remove accidental copies in your source; use unique transaction references for genuinely separate entries.'
        if 'Missing amount' in text: return 'Enter a verified value if available. Otherwise leave it unknown and review the planning estimate; do not enter zero unless confirmed.'
        if 'negative' in text.lower() or 'sign' in text.lower(): return 'Check refunds and credit signs. For negative expense exports, select the negative-expense option. Never remove a minus sign just to pass a check.'
        return 'Correct the value using dot decimals, for example 1,234.50 CAD. Currency conversion and decimal-comma amounts are not automatic.'
    out['Next step']=out['Issue'].map(action)
    return out


from dataclasses import dataclass, asdict
import math
import pandas as pd


@dataclass(frozen=True)
class Plan:
    monthly_revenue: float = 0
    cogs_ratio: float = 0.30
    payroll: float = 0
    rent: float = 0
    other: float = 0
    capex: float = 0
    deposit_inventory_fees: float = 0
    equity: float = 0
    loan: float = 0
    interest: float = 0.08
    term: int = 60
    delay: int = 0
    delay_staff: float = .25
    delay_other: float = .50
    annual_growth: float = .05
    annual_inflation: float = .03
    maintenance: float = 250
    reserve: float = 20000
    ramp_months: int = 6
    ramp_start: float = .60
    start: str = '2027-01-01'
    seasonality: tuple = (1.,)*12


def validate(plan):
    for name, value in asdict(plan).items():
        if name in ('start','seasonality'):
            continue
        if not isinstance(value, (int,float)) or isinstance(value,bool) or not math.isfinite(value):
            raise ValueError(f'{name} must be a finite number.')
    for key in ['monthly_revenue','payroll','rent','other','capex','deposit_inventory_fees','equity','loan','maintenance','reserve']:
        if not 0 <= getattr(plan,key) <= 1e12:
            raise ValueError(f'{key} must be between 0 and one trillion.')
    for key in ['cogs_ratio','interest','delay_staff','delay_other','ramp_start']:
        if not 0 <= getattr(plan,key) <= 1:
            raise ValueError(f'{key} must be between 0 and 100%.')
    for key in ['annual_growth','annual_inflation']:
        if not -.5 <= getattr(plan,key) <= 1:
            raise ValueError(f'{key} must be between -50% and 100%.')
    for key, low, high in [('term',1,360),('delay',0,12),('ramp_months',0,24)]:
        val=getattr(plan,key)
        if int(val)!=val or not low<=val<=high:
            raise ValueError(f'{key} must be a whole number from {low} to {high}.')
    if len(plan.seasonality)!=12 or any(not math.isfinite(float(x)) or x<0 for x in plan.seasonality) or sum(plan.seasonality)<=0:
        raise ValueError('Provide 12 non-negative seasonal factors with a positive total.')
    start=pd.Timestamp(plan.start)
    if pd.isna(start) or start.day!=1:
        raise ValueError('The forecast must start on the first day of a month.')


def payment(principal, annual_rate, months):
    r=annual_rate/12
    return principal/months if r==0 else principal*r/(-math.expm1(-months*math.log1p(r)))


def forecast(plan, revenue_factor=1.0, payroll_factor=1.0):
    validate(plan)
    if any(not math.isfinite(x) or x<0 for x in (revenue_factor,payroll_factor)):
        raise ValueError('Scenario multipliers must be non-negative finite numbers.')
    debt=plan.loan
    opening=plan.equity+plan.loan-plan.capex-plan.deposit_inventory_fees
    cash=opening
    monthly_payment=payment(plan.loan,plan.interest,plan.term)
    seasons=[x/(sum(plan.seasonality)/12) for x in plan.seasonality]
    rows=[]
    for i, period in enumerate(pd.date_range(plan.start,periods=36,freq='MS')):
        opened=i>=plan.delay
        age=i-plan.delay
        ramp=(plan.ramp_start+(1-plan.ramp_start)*min(age/max(plan.ramp_months-1,1),1)) if opened and plan.ramp_months>1 else 1
        yr=i//12
        revenue=plan.monthly_revenue*revenue_factor*(1+plan.annual_growth)**yr*seasons[period.month-1]*ramp if opened else 0
        cogs=revenue*plan.cogs_ratio
        inflation=(1+plan.annual_inflation)**yr
        payroll=plan.payroll*payroll_factor*inflation*(1 if opened else plan.delay_staff)
        rent=plan.rent*inflation
        other=plan.other*inflation*(1 if opened else plan.delay_other)
        ebitda=revenue-cogs-payroll-rent-other
        interest=debt*plan.interest/12 if debt>0 else 0
        principal=(debt if i==plan.term-1 else min(debt,max(0,monthly_payment-interest))) if i<plan.term else 0
        debt=max(0,debt-principal)
        maintenance=plan.maintenance if opened else 0
        depreciation=plan.capex/60 if opened else 0
        net=ebitda-interest-principal-maintenance
        cash+=net
        fixed=payroll+rent+other+interest+principal+maintenance
        breakeven=fixed/(1-plan.cogs_ratio) if plan.cogs_ratio<1 else float('nan')
        rows.append({'Month':period,'Open':opened,'Revenue':revenue,'COGS':cogs,'Payroll':payroll,'Rent':rent,'Other costs':other,
                     'EBITDA':ebitda,'Depreciation':depreciation,'Interest':interest,'Pre-tax profit':ebitda-depreciation-interest,
                     'Loan principal':principal,'Debt balance':debt,'Maintenance spending':maintenance,'Net cash flow':net,'Closing cash':cash,
                     'Cash break-even revenue':breakeven})
    df=pd.DataFrame(rows)
    minimum=min(opening,df['Closing cash'].min())
    summary={'Opening cash':opening,'Year 1 revenue':df.Revenue.iloc[:12].sum(),'Year 1 EBITDA':df.EBITDA.iloc[:12].sum(),
             'Year 1 pre-tax profit':df['Pre-tax profit'].iloc[:12].sum(),'Year 1 net cash flow':df['Net cash flow'].iloc[:12].sum(),
             'Lowest cash (including opening)':minimum,'Extra funding to maintain reserve':max(0,plan.reserve-minimum),
             'Month 36 cash':cash,'Monthly loan payment':monthly_payment}
    return df,summary


def report(plan, summaries, source_notes):
    lines=['# Expansion feasibility report','', 'Illustrative forecast in CAD. Historical data is not proof of future demand.',
           'No tax, sales-tax timing, working-capital changes, cannibalization, terminal value or owner distributions are modelled.',
           'Amounts are received/paid in the same month. Funding and initial uses occur before month 1. No automatic gap borrowing.',
           'Depreciation uses 60 months; maintenance spending has no additional depreciation in this simplified model.',
           'Seasonality is normalized to average 1; growth/inflation step every 12 forecast months. Delay does not extend the horizon.',
           '', '## Data review',source_notes,'','## Confirmed assumptions']
    lines += [f'- {k}: {v}' for k,v in asdict(plan).items()]
    for name,summary in summaries.items():
        lines+=['',f'## {name}']+[f'- {k}: CAD {v:,.2f}' for k,v in summary.items()]
    lines+=['','## Before committing','Validate local demand and purchase mix; obtain lease and supplier quotes; confirm funding and opening dates; obtain a tax-aware forecast.']
    return '\n'.join(lines)


import re
import math
import pandas as pd

EXCLUDE='Exclude from operating history'
REVIEW='Needs review'

def subtotal_candidates(frame):
    pattern=r'(?i)\b(subtotal|grand total|opening balance|closing balance|net profit|gross profit|total income|total expenses)\b|^total(?:\s|$)'
    return [i for i,row in enumerate(frame.itertuples(index=False,name=None)) if any(re.search(pattern,str(v).strip()) for v in row)]

def convert_amount(value,currency,rate):
    code=str(currency).strip().upper()
    if not re.fullmatch('[A-Z]{3}',code):
        raise ValueError('Provide a three-letter currency code for every included row, such as CAD or USD.')
    try: factor=float(rate)
    except (ValueError,TypeError): raise ValueError('Supply a positive CAD-per-unit exchange rate for every foreign-currency row.')
    if not math.isfinite(factor) or factor<=0 or (code=='CAD' and factor!=1):
        raise ValueError('Rates must be positive and finite; CAD must use 1. Rate means CAD for one source-currency unit.')
    if pd.isna(value):return None
    text=str(value).strip()
    found=re.findall(r'\b[A-Za-z]{3}\b',text)
    if any(token.upper()!=code for token in found):
        raise ValueError('An amount currency label conflicts with the selected currency. Correct it before conversion.')
    if code!='CAD': text=re.sub(r'\b'+code+r'\b','',text,flags=re.I).strip()
    val=number(text)
    if val is None:return None
    converted=val*factor
    if not math.isfinite(converted) or abs(converted)>1e12:raise ValueError('Converted amount exceeds the supported range.')
    return converted

def fx_convert(frame,amount_columns,currency_column,rate_column):
    if not amount_columns:raise ValueError('Select the monetary columns to convert.')
    if currency_column in amount_columns or rate_column in amount_columns:raise ValueError('Currency and rate columns cannot also be amount columns.')
    out=frame.copy().astype(object)
    for i,row in frame.iterrows():
        for col in amount_columns:
            try: out.loc[i,col]=convert_amount(row[col],row[currency_column],1 if str(row[currency_column]).strip().upper()=='CAD' else row[rate_column])
            except ValueError as exc:raise ValueError(f'Row {i+1}, {col}: {exc}') from exc
    return out

def prepare_bank(frame,date_column,category_column,choices,amount_column=None,debit_column=None,credit_column=None,order='ISO / year first'):
    columns=[date_column,category_column]+([amount_column] if amount_column else [debit_column,credit_column])
    if len(set(columns))!=len(columns):raise ValueError('Date, category and amount columns must be different.')
    included=frame[frame[category_column].astype(str).map(choices)!=EXCLUDE]
    if included.astype(str).duplicated().any():
        raise ValueError('Possible duplicate bank rows. Review them and exclude accidental copies, or supply unique references for separate transactions.')
    records=[]
    for i,row in frame.iterrows():
        category=choices.get(str(row[category_column]),REVIEW)
        if category==EXCLUDE:continue
        if category not in FINANCIAL:raise ValueError(f'Choose a category or explicit exclusion for {row[category_column]!s}.')
        try:
            period=month(row[date_column],order)
            if amount_column: amount=number(row[amount_column])
            else:
                debit=number(row[debit_column]); credit=number(row[credit_column])
                if any(v is not None and v<0 for v in [debit,credit]):raise ValueError('Debit/credit columns must use nonnegative amounts.')
                if debit and credit:raise ValueError('Both debit and credit contain amounts. Resolve this row before preparing.')
                amount=None if debit is None and credit is None else (credit or 0)-(debit or 0)
            # Signed bank amount: inflows positive. Expense refunds therefore reduce cost.
            value=amount if category=='revenue' or amount is None else -amount
            records.append({'period':period,'field':category,'value':value})
        except ValueError as exc:raise ValueError(f'Source row {i+1}: {exc}') from exc
    if not records:raise ValueError('No included operating transactions remain.')
    long=pd.DataFrame(records)
    rows=[]
    for period,group in long.groupby('period'):
        item={'Month':period.strftime('%Y-%m')}
        for field in FINANCIAL:
            values=group.loc[group.field==field,'value']
            item[FIELDS[field]]=float(values.sum()) if len(values) and values.notna().all() else None
        rows.append(item)
    # Use canonical aliases for compatibility with the standard review.
    return pd.DataFrame(rows).rename(columns={FIELDS[f]:f for f in FINANCIAL})

def prepare_sideways(frame,label_column,period_columns,choices):
    if not period_columns:raise ValueError('Select at least one monthly column, excluding Total/YTD.')
    periods=[month(c) for c in period_columns]
    if len(set(periods))!=len(periods):raise ValueError('Two selected columns describe the same month. Select one.')
    selected={}
    for i,row in frame.iterrows():
        field=choices.get(i,REVIEW)
        if field==EXCLUDE:continue
        if field not in FINANCIAL:raise ValueError(f'Choose a category or exclusion for row {i+1}: {row[label_column]}.')
        selected.setdefault(field,[]).append(i)
    if not selected:raise ValueError('Select at least one operating category.')
    indices=[i for group in selected.values() for i in group]
    if frame.loc[indices].astype(str).duplicated().any():raise ValueError('Possible duplicate report rows. Exclude copies or supply distinct account references before combining.')
    result=[]
    for col,period in zip(period_columns,periods):
        item={'Month':period.strftime('%Y-%m')}
        for field,indices in selected.items():
            vals=[number(frame.loc[i,col]) for i in indices]
            item[field]=sum(vals) if all(v is not None for v in vals) else None
        result.append(item)
    return pd.DataFrame(result)


